  def reverseString(s: Array[Char], start: Int, end: Int): Unit = {
    var (left, right) = (start, end)
    while (left < right) {
      var tmp = s(left)
      s(left) = s(right)
      s(right) = tmp
      left += 1
      right -= 1
    }
  }

  // 翻转每个单词
  def reverseEachWord(s: Array[Char]): Unit = {
    var i = 0
    while (i < s.length) {
      var j = i + 1
      // 向后迭代寻找每个单词的坐标
      while (j < s.length && s(j) != ' ') j += 1
      reverseString(s, i, j - 1)  // 翻转每个单词
      i = j + 1   // i往后更新
    }
  }
}
